// Replaces the old "Edit Fields" + "format data" pair — extracts once,
// correctly, instead of extracting the name twice (the second pass ran on
// the already-extracted name, not the raw event) and instead of trusting
// attendees[0]/[1] positionally (Google doesn't guarantee attendee order,
// so that could silently pick the organizer instead of the lead).
const results = [];

for (const item of items) {
  const ev = item.json;
  if (!ev.id || ev.status === 'cancelled') continue;

  const start = ev.start && (ev.start.dateTime || ev.start.date);
  const end = ev.end && (ev.end.dateTime || ev.end.date);
  if (!start) continue;

  const attendees = ev.attendees || [];
  const lead = attendees.find((a) => a && a.email && !a.organizer && !a.resource) || attendees.find((a) => a && a.email);
  const email = lead && lead.email;
  if (!email) continue;

  const summary = ev.summary || '';
  const parenMatch = summary.match(/\(([^)]+)\)/);
  const rawName = parenMatch ? parenMatch[1] : (lead.displayName || email.split('@')[0]);
  const cleanName = rawName
    .trim()
    .split(/\s+/)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
  const nameParts = cleanName.split(' ');
  const firstName = nameParts[0] || 'Unknown';
  const lastName = nameParts.slice(1).join(' ') || '-';

  results.push({
    json: {
      googleEventId: ev.id,
      subject: summary || 'Booked Meeting',
      dueAt: start,
      endAt: end || null,
      displayStart: new Date(start).toLocaleString(undefined, {
        dateStyle: 'medium',
        timeStyle: 'short',
      }),
      email,
      name: cleanName,
      firstName,
      lastName,
    },
  });
}

return results;
